func _ready() -> void:
	# Create the Player scene
	var player := CharacterBody2D.new()
	player.name = "Player"
	player.script = load("res://scripts/Player.gd")

	# Create the StateMachine node
	var sm := StateMachine.new()
	sm.name = "StateMachine"
	sm.script = load("res://scripts/StateMachine.gd")
	player.add_child(sm)
	sm.owner = player

	# Create state nodes
	var states := {
		"Idle": load("res://scripts/states/IdleState.gd"),
		"Run": load("res://scripts/states/RunState.gd"),
		"Jump": load("res://scripts/states/JumpState.gd"),
		"Fall": load("res://scripts/states/FallState.gd"),
		"Attack": load("res://scripts/states/AttackState.gd"),
	}

	for state_name in states:
		var state_node := Node.new()
		state_node.name = state_name
		state_node.script = states[state_name]
		sm.add_child(state_node)
		state_node.owner = player

	# Add a CollisionShape2D
	var collision := CollisionShape2D.new()
	collision.name = "CollisionShape2D"
	var rect := RectangleShape2D.new()
	rect.size = Vector2(64, 64)
	collision.shape = rect
	player.add_child(collision)
	collision.owner = player

	# Pack and save the scene
	var packed := PackedScene.new()
	packed.pack(player)

	var err := ResourceSaver.save(packed, "res://scenes/Player.tscn")
	if err != OK:
		printerr("Failed to save scene: ", err)
	else:
		print("Scene saved successfully.")

	get_tree().quit()

